package org.opengridseg.detect;
import java.util.*; import org.opengridseg.image.*;
public final class DetectionEngine { private DetectionEngine(){} public static DetectionResult detect(FloatPlane source,DetectionParameters parameters){double angle=OrientationEstimator.estimateDegrees(source);RotatedImage rotated=ExpandedRotation.rotate(source,angle,Interpolation.BILINEAR);List<Peak> peaks=MatchedBarDetector.detect(rotated.plane(),parameters);if(peaks.size()<4)throw new IllegalArgumentException("Too few matched-filter peaks: "+peaks.size());Pitch estimated=GridFitter.estimatePitch(peaks,parameters.minPitch,parameters.maxPitch,12.0);Pitch pitch=new Pitch(Double.isFinite(parameters.pitchX)?parameters.pitchX:estimated.x(),Double.isFinite(parameters.pitchY)?parameters.pitchY:estimated.y());GridPhase phase=GridFitter.fitPhase(peaks,pitch,parameters.gridTolerance);List<MacroArray> arrays=MacroLayoutFitter.fit(peaks,phase,pitch,parameters.arraySize,parameters.macroPeriodSlots,parameters.minArrayPeaks);if(arrays.isEmpty())throw new IllegalArgumentException("No 20x20 array has enough direct peaks");return new DetectionResult(angle,rotated,peaks,pitch,phase,arrays);} }
